<?php require_once dirname(__FILE__).'/../_clan_port/lib.php';
require_params(array('userid','gserver','chname','clName','clwon','clwonUserid','lv','chtype','chlv'));$c=db_connect_clan();if(!$c)code_exit(100);$leader=req('chname');$cn=req('clName');$target=req('clwon');
$s=q($c,'SELECT TOP 1 IDX,ClanZang,MemCnt FROM dbo.CL WHERE ClanName=?',array($cn));if(!$s)fail_db($c);$cl=fetch_row($s);if($cl===false){@odbc_close($c);code_exit(0);} $members=intval(field($cl,'MemCnt')); if(($members+1)>100){@odbc_close($c);code_exit(2);} 
$s=q($c,'SELECT TOP 1 ChName FROM dbo.UL WHERE Permi=2 AND ClanName=?',array($cn));if(!$s)fail_db($c);$sub=fetch_row($s);$subname=$sub===false?'':field($sub,'ChName');if(field($cl,'ClanZang')!==$leader&&$subname!==$leader){@odbc_close($c);code_exit(0);}
$s=q($c,'SELECT TOP 1 ClanName FROM dbo.UL WHERE ChName=?',array($target));if(!$s)fail_db($c);$u=fetch_row($s);if($u!==false&&field($u,'ClanName')!==''){@odbc_close($c);code_exit(0);}if($u!==false)q($c,'DELETE FROM dbo.UL WHERE ChName=?',array($target));$members++;if($members>25){@odbc_close($c);code_exit(4);}if(!begin_tx($c))fail_db($c);
$a=q($c,'UPDATE dbo.CL SET MemCnt=? WHERE ClanName=?',array($members,$cn));$b=$a?q($c,'INSERT INTO dbo.UL ([IDX],[userid],[ChName],[ClanName],[ChType],[ChLv],[Permi],[JoinDate],[DelActive],[PFlag],[KFlag],[MIconCnt]) VALUES (?,?,?,?,?,?,0,GETDATE(),0,0,0,0)',array(field($cl,'IDX'),req('clwonUserid'),$target,$cn,req('chtype'),req('chlv'))):false;if(!$a||!$b){rollback_tx($c);@odbc_close($c);code_exit(100);}commit_tx($c);@odbc_close($c);code_exit(1); ?>